/**
 * GIBS colour maps — generated by scripts/refresh-gibs-colormaps.mjs.
 *
 * Each entry is the value table GIBS uses to paint a layer: for every
 * palette index (ref) the physical quantity it stands for, as a range.
 * A measurement reads the pixel's index and looks it up here.
 *
 * Captured from https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/1.0.0/WMTSCapabilities.xml on 2026-10-29.
 *
 * Do not edit by hand — run the script to regenerate.
 */

export interface GibsColormap {
  /** Physical unit, as published by GIBS. */
  units: string | null;
  /** Palette indices, ascending. */
  refs: number[];
  /** Lower bound of the value range for each ref, parallel to refs. */
  lows: number[];
  /** Upper bound of the value range for each ref, parallel to refs. */
  highs: number[];
  /** Palette indices that mean "no observation". */
  nodata: number[];
  /**
   * Palette indices GIBS renders as transparent — the raster carries a
   * value but not an observation of the quantity the layer measures.
   */
  transparent: number[];
}

