export const GIBS_COLORMAPS_CAPTURED = "2026-10-29";

/**
 * Look up the value range for a palette index.
 *
 * Returns null for an index that is not in the table, that marks no
 * observation, or that GIBS renders as transparent — the caller must
 * treat that as missing data, never as zero.
 */
export function colormapRange(
  colormap: GibsColormap,
  index: number,
): [number, number] | null {
  if (colormap.nodata.includes(index)) return null;
  if (colormap.transparent.includes(index)) return null;
  const at = colormap.refs.indexOf(index);
  if (at === -1) return null;
  return [colormap.lows[at], colormap.highs[at]];
}
